const cfg = $('CONFIG - Edit These Values').first().json;
const gaTotal = $('GA4 - Overall Totals').first().json;
const gaSources = $('GA4 - Traffic Sources').first().json;
const gaLanding = $('GA4 - Landing Pages').first().json;
const gscQueries = $('Search Console - Queries').first().json;
const gscPages = $('Search Console - Pages').first().json;
const metric = (report, name) => { const i = (report.metricHeaders || []).findIndex(h => h.name === name); return i < 0 ? 0 : Number(report.rows?.[0]?.metricValues?.[i]?.value || 0); };
const gaRows = (report, d, m) => (report.rows || []).map(r => [...d.map((_, i) => r.dimensionValues?.[i]?.value || ''), ...m.map((_, i) => Number(r.metricValues?.[i]?.value || 0))]);
const gscRows = report => (report.rows || []).map(r => [r.keys?.[0] || '', Number(r.clicks || 0), Number(r.impressions || 0), Number(r.ctr || 0), Number(r.position || 0)]);
const sessions = metric(gaTotal, 'sessions'), users = metric(gaTotal, 'totalUsers'), newUsers = metric(gaTotal, 'newUsers'), views = metric(gaTotal, 'screenPageViews'), engaged = metric(gaTotal, 'engagedSessions');
const duration = metric(gaTotal, 'averageSessionDuration'), bounce = metric(gaTotal, 'bounceRate');
const sourceData = gaRows(gaSources, ['channel','sourceMedium'], ['sessions','totalUsers','engagedSessions']);
const landingData = gaRows(gaLanding, ['landingPage'], ['sessions','totalUsers','engagedSessions']);
const queryData = gscRows(gscQueries), pageData = gscRows(gscPages);
const clicks = queryData.reduce((a,r)=>a+r[1],0), impressions = queryData.reduce((a,r)=>a+r[2],0);
const ctr = impressions ? clicks/impressions : 0;
const avgPosition = impressions ? queryData.reduce((a,r)=>a+(r[4]*r[2]),0)/impressions : 0;
const topSources = sourceData.slice(0,5).map(r => [r[0],r[1],r[2],sessions?r[2]/sessions:0,r[2]?r[4]/r[2]:0,r[3]]);
const topLanding = landingData.slice(0,5).map(r => [r[0],r[1],sessions?r[1]/sessions:0,r[1]?r[3]/r[1]:0,r[2],'']);
const opportunities = queryData.filter(r => r[2] >= 10 && r[4] <= 20).sort((a,b) => (b[2]*(1-b[3]))-(a[2]*(1-a[3]))).slice(0,5).map(r => [...r, r[4] <= 10 ? 'Improve title/meta to win more clicks' : 'Improve page to reach page one']);
while (topSources.length < 5) topSources.push(['','','','','','']); while (topLanding.length < 5) topLanding.push(['','','','','','']); while (opportunities.length < 5) opportunities.push(['','','','','','']);
const topSource = sourceData[0] || ['', '', 0, 0, 0], topPage = landingData[0] || ['',0,0,0], topQuery = queryData[0] || ['',0,0,0,0], topSearchPage = pageData[0] || ['',0,0,0,0];
const sourceShare = sessions ? topSource[2]/sessions : 0, engagementRate = sessions ? engaged/sessions : 0, pagesPerSession = sessions ? views/sessions : 0;
const insights = [
`Traffic: ${sessions.toLocaleString()} sessions from ${users.toLocaleString()} users; ${Math.round(engagementRate*100)}% were engaged.`,
`Acquisition: ${topSource[0] || 'No channel'} is the leading channel (${Math.round(sourceShare*100)}% of sessions), led by ${topSource[1] || 'no source data'}.`,
`Content: ${topPage[0] || 'No landing-page data'} is the top entry page with ${(topPage[1]||0).toLocaleString()} sessions.`,
`Search: ${(clicks||0).toLocaleString()} clicks from ${(impressions||0).toLocaleString()} impressions (${(ctr*100).toFixed(1)}% CTR) across the top 100 queries.`,
opportunities[0][0] ? `Priority: improve “${opportunities[0][0]}” — ${opportunities[0][2]} impressions at position ${Number(opportunities[0][4]).toFixed(1)}.` : 'Priority: build more search visibility; no high-impression near-page-one query was found.'
];
const overview = [
['EXECUTIVE WEBSITE PERFORMANCE SUMMARY','','','','',''],
[`Last ${cfg.days} days ending yesterday`,`Generated ${$now.toFormat('MMM d, yyyy')}`,cfg.search_console_site_url,'','',''],
['EXECUTIVE SNAPSHOT','','','','',''],
['Sessions','Users','Page Views','Engagement Rate','Pages / Session','Avg. Session (sec)'],
[sessions,users,views,engagementRate,pagesPerSession,duration],
['New Users','Estimated Returning','Bounce Rate','Engaged Sessions','Search Clicks','Search Impressions'],
[newUsers,Math.max(0,users-newUsers),bounce,engaged,clicks,impressions],
['','','','','',''],
['ACQUISITION: TOP TRAFFIC SOURCES','','','','',''],
['Channel','Source / Medium','Sessions','Traffic Share','Engagement Rate','Users'],...topSources,
['','','','','',''],
['CONTENT: TOP LANDING PAGES','','','','',''],
['Landing Page','Sessions','Traffic Share','Engagement Rate','Users',''],...topLanding,
['','','','','',''],
['ORGANIC SEARCH SNAPSHOT','','','','',''],
['Clicks','Impressions','CTR','Avg. Position','Top Query','Top Search Page'],
[clicks,impressions,ctr,avgPosition,topQuery[0],topSearchPage[0]],
['','','','','',''],
['SEO OPPORTUNITIES','','','','',''],
['Query','Clicks','Impressions','CTR','Avg. Position','Recommended Action'],...opportunities,
['','','','','',''],
['ANALYST TAKEAWAYS','','','','',''],...insights.map(x=>[x,'','','','',''])
];
const sources = [['Channel','Source / medium','Sessions','Users','Engaged sessions'], ...sourceData];
const landing = [['Landing page','Sessions','Users','Engaged sessions'], ...landingData];
const queries = [['Search query','Clicks','Impressions','CTR','Average position'], ...queryData];
const pages = [['Search result page','Clicks','Impressions','CTR','Average position'], ...pageData];
return [{json:{spreadsheetTitle:`${cfg.spreadsheet_name} - ${$now.toFormat('yyyy-MM-dd')}`,batchUpdateBody:{valueInputOption:'USER_ENTERED',data:[{range:'Overview!A1',values:overview},{range:'Traffic Sources!A1',values:sources},{range:'Landing Pages!A1',values:landing},{range:'Search Queries!A1',values:queries},{range:'Search Pages!A1',values:pages}]}}}];
